import { useErrorContextValue, useGet, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Alert, Button, Col, Icon, Row, Spin, Table } from 'antd'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { connect } from 'react-redux'
import { useHistory } from 'react-router'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { EbSectionWrapper, RowWithMargin } from '../../../CommonComponents'
import Filters from '../../../components/Filters'
import { broadCastCenterApiConfig } from '../apiConfig'
import { broadCastCenterColumns, getFiltersFields } from './utility'

const BroadcastCenterContainer = (props) => {
  const [postList, postListRequest] = useGet(broadCastCenterApiConfig.getBroadcastPosts)
  const [configData, configRequest] = useGet(broadCastCenterApiConfig.getBroadcastConfig)
  const [recipientsData, getRecipients] = useGet(broadCastCenterApiConfig.getRecipientList)
  const [{ POST_LIST_ERROR, postListStatus }] = useErrorContextValue()
  const [{ POST_LIST_LOADER, CONFIG_LOADER }] = useLoaderContextValue()
  const [filters, setFilters] = useState({})
  const [listMetaData, setListMetaData] = useState({})
  const history = useHistory()
  const [showEdit, setShowEdit] = useState(false)
  const [showDetails, setShowDetails] = useState(false)

  const recipients = useMemo(() => {
    const options = recipientsData?.data?.map(({ id, name }) => ({ code: id, name: `${id} - ${name}` })) || []
    return [{ code: 'all', name: 'All' }, ...options]
  }, [recipientsData])

  const statuses = useMemo(() => {
    const statusData = configData?.broadcast_status || []
    const statusDisplayObject = {}
    statusData.forEach((status) => {
      statusDisplayObject[status.code] = status.name
    })
    return statusDisplayObject
  }, [configData])

  const columns = useMemo(() => {
    return broadCastCenterColumns({ statuses, history, showDetails, showEdit })
  }, [history, statuses, showDetails, showEdit])

  const filterFields = useMemo(() => {
    const fieldsConfig = configData || {}
    return getFiltersFields({ ...fieldsConfig, recipients })
  }, [configData, recipients])

  const postListRemapped = useMemo(() => {
    return Array.isArray(postList?.data) ? postList.data : []
  }, [postList])

  const handleAddPost = useCallback(() => {
    history.push('/employee-benefits/broadcast-center/add-post')
  }, [history])

  const handleTableChange = (params) => {
    const query = {
      page: params.current,
      per_page: params.pageSize
    }
    postListRequest({ ...query, ...filters })
  }

  useEffect(() => {
    const metaData = postList?.meta_data
    if (metaData) {
      setListMetaData(metaData)
    }
  }, [postList])

  useEffect(() => {
    postListRequest()
    configRequest()
  }, [postListRequest, configRequest])

  useEffect(() => {
    getRecipients()
  }, [getRecipients])

  useEffect(() => {
    if (Array.isArray(props.permissions)) {
      for (const permission of props.permissions) {
        if (['ops.eb_update_broadcast', 'ops.eb_update_publish_broadcast'].includes(permission)) {
          setShowEdit(true)
        }
        if (permission === 'ops.eb_view_broadcast_detail') {
          setShowDetails(true)
        }
      }
    }
  }, [props.permissions])

  return (
    <>
      <EbSectionWrapper>
        <Row type='flex' justify='space-between' align='middle'>
          <Col>
            <h2>Broadcast Center</h2>
          </Col>
          <Col>
            <PermissionCheckerV2 requiredPermission='ops.eb_create_broadcast'>
              <Button
                type='primary'
                onClick={handleAddPost}
              >
                Add Post <Icon type='plus' />
              </Button>
            </PermissionCheckerV2>
          </Col>
        </Row>
        <Spin spinning={!!POST_LIST_LOADER || !!CONFIG_LOADER}>
          {POST_LIST_ERROR && <Alert type='error' message={postListStatus} banner />}
          <Filters
            fields={filterFields}
            onFilter={setFilters}
            request={postListRequest}
          />
        </Spin>
      </EbSectionWrapper>
      <RowWithMargin />
      <EbSectionWrapper>
        <Row>
          <Col><h2>Broadcast List</h2></Col>
        </Row>
        <Spin spinning={!!POST_LIST_LOADER}>
          <Table
            dataSource={postListRemapped}
            rowKey={({ id }) => id}
            columns={columns}
            pagination={{
              pageSize: listMetaData.page_size,
              total: listMetaData.total_records,
              current: listMetaData.page
            }}
            onChange={handleTableChange}
          />
        </Spin>
      </EbSectionWrapper>
    </>
  )
}
export default connect(
  state => ({ permissions: state.Auth.permissions })
)(BroadcastCenterContainer)
