import { Form, Select } from 'antd'
import { useEffect } from 'react'

const SelectFilter = ({
  name,
  label,
  options,
  placeholder,
  getFieldDecorator,
  loading,
  mode,
  value,
  setFieldsValue,
  onChange = () => {},
  isOptionDisabled = () => false
}) => {
  useEffect(() => {
    if (value) {
      onChange({ value, setFieldsValue })
    }
  }, [value, onChange, setFieldsValue])

  return (
    <Form.Item label={label} labelAlign='left'>
      {
        getFieldDecorator(name, {})(
          <Select
            placeholder={placeholder}
            loading={!!loading}
            allowClear
            {...(mode && { mode })}
            filterOption={(input: any, option: any) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
          >
            {
              options.map(({ name, code }, index) => (
                <Select.Option
                  key={name}
                  value={code}
                  disabled={isOptionDisabled({ index, value })}
                >
                  {name}
                </Select.Option>
              ))
            }
          </Select>
        )
      }
    </Form.Item>
  )
}
export default SelectFilter
