import { Icon, Tag } from 'antd'
import moment from 'moment-timezone'
import { statusColor } from './constants'
import { NoPaddingButton, TitleSpan } from './index.style'

export const getFiltersFields = ({ broadcast_status: broadcastStatus, recipients }) => {
  return [
    {
      type: 'text',
      name: 'broadcast_id',
      label: 'Broadcase ID',
      placeholder: '1',
      maxLength: 10
    },
    {
      type: 'select',
      name: 'broadcast_status',
      label: 'Broadcast Status',
      placeholder: 'Published',
      options: Array.isArray(broadcastStatus) ? broadcastStatus : []
    },
    {
      type: 'text',
      name: 'subject',
      label: 'Title',
      placeholder: ''
    },
    {
      type: 'date-range',
      name: 'created-at',
      label: 'Created At',
      startKey: 'created_at_start_date',
      endKey: 'created_at_end_date',
      placeholder: undefined
    },
    {
      type: 'select',
      name: 'recipients',
      label: 'Recipients',
      placeholder: undefined,
      options: recipients || [],
      mode: 'multiple',
      normalize: (recipients, toBeSentValues) => {
        toBeSentValues.is_all_recipients = undefined
        if (!recipients?.length) return
        if (recipients?.length === 1 && recipients[0] === 'all') {
          toBeSentValues.is_all_recipients = true
        }
        return recipients.filter(recipient => recipient !== 'all')
      },
      onChange: ({ value, setFieldsValue }) => {
        if (value && value.indexOf('all') >= 0 && value.length > 1) {
          setFieldsValue({ recipients: ['all'] })
        }
      },
      isOptionDisabled: ({ value, index }) => {
        if (value?.length === 1 && value[0] === 'all' && index > 0) {
          return true
        }
        return false
      }
    },
    {
      type: 'date-range',
      name: 'published-at',
      label: 'Published At',
      startKey: 'publish_at_start_date',
      endKey: 'publish_at_end_date',
      placeholder: undefined
    },
    {
      type: 'text',
      name: 'updated_by',
      label: 'Creator',
      placeholder: 'xyz@pasarpolis.com',
      options: []
    }
  ]
}

export const broadCastCenterColumns = ({ history, statuses, showDetails, showEdit }) => {
  return [
    {
      title: 'Broadcast ID',
      dataIndex: 'id'
    },
    {
      title: 'Title',
      dataIndex: 'subject',
      render: (subject) => <TitleSpan>{subject}</TitleSpan>,
      width: 250
    },
    {
      title: 'Recipients',
      dataIndex: 'recipients',
      // render: recipients => recipients?.length === 0 ? 'All' : recipients.map(recipient => `${recipient.id} - ${recipient.name}`).join(', ')
      render: recipients => recipients?.length === 0 ? 'All' : recipients.map(recipient => recipient.name).join(', ')
    },
    {
      title: 'Created At',
      dataIndex: 'created_at',
      render: d => moment(new Date(d)).tz('Asia/Jakarta').format('DD-MM-YYYY HH:mm')
    },
    {
      title: 'Published At',
      dataIndex: 'publish_at',
      render: d => d && moment(new Date(d)).tz('Asia/Jakarta').format('DD-MM-YYYY HH:mm')
    },
    {
      title: 'Broadcast Status',
      dataIndex: 'broadcast_status',
      render: status => <Tag color={statusColor[status]}>{statuses[status] || status}</Tag>
    },
    {
      title: 'Creator',
      dataIndex: 'updated_by'
    },
    {
      title: 'Action',
      render: (rowData) => ['PUBLISHED', 'IN_PROGRESS_TO_PUBLISH'].includes(rowData.broadcast_status)
        ? (
          <NoPaddingButton
            type='link'
            onClick={() => history.push(`/employee-benefits/broadcast-center/post/${rowData.id}`)}
            disabled={!showDetails}
          >
            Details <Icon type='eye' />
          </NoPaddingButton>
          )
        : (
          <NoPaddingButton
            type='link'
            onClick={() => history.push({ pathname: `/employee-benefits/broadcast-center/edit-post/${rowData.id}`, state: rowData })}
            disabled={!showEdit}
          >
            Edit <Icon type='edit' />
          </NoPaddingButton>
          )
    }
  ]
}
