import { Button, Col, Form, Icon, Row } from 'antd'
import { useCallback, useEffect } from 'react'
import { RowWithMargin } from '../../CommonComponents'
import { horizontalLayout } from '../../utils/formLayout'
import FilterField from './FilterField'

const defaultFormat = 'YYYY-MM-DD'

const Filters = ({ form, fields = [], request = () => {}, onFilter }) => {
  const {
    validateFields,
    getFieldDecorator,
    setFieldsValue,
    resetFields,
    getFieldsValue
  } = form

  const values = getFieldsValue()

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    validateFields((error, values) => {
      if (!error) {
        const toBeSentValues = { ...values }
        for (const key in values) {
          const valueField = fields.find(field => field.name === key)
          if (valueField && valueField.type === 'date-range') {
            toBeSentValues[valueField.startKey] = values[key]?.[0]?.format(valueField.format || defaultFormat)
            toBeSentValues[valueField.endKey] = values[key]?.[1]?.format(valueField.format || defaultFormat)
            delete toBeSentValues[key]
          }
          if (valueField.normalize) {
            toBeSentValues[key] = valueField.normalize(toBeSentValues[key], toBeSentValues)
          }
        }
        onFilter(toBeSentValues)
        request(toBeSentValues)
      }
    })
  }, [validateFields, request, fields, onFilter])

  const handleReset = useCallback(() => {
    resetFields()
    request()
    onFilter({})
  }, [resetFields, request, onFilter])

  useEffect(() => {
    fields.forEach(field => {
      setFieldsValue({
        [field.name]: field.initialValue
      })
    })
  }, [fields, setFieldsValue])

  return (
    <div>
      <RowWithMargin gutter={80}>
        {/* <Col span={20}>
          <h3>Filters</h3>
        </Col> */}
      </RowWithMargin>
      <Form
        onSubmit={handleSubmit}
        layout='horizontal'
        {...horizontalLayout}
      >
        <fieldset>
          <Row type='flex' align='bottom'>
            <Col span={24}>
              <Row gutter={80}>
                {
                  fields.map(({ ...field }) => (
                    <Col key={field.name} span={12}>
                      <FilterField
                        {...field}
                        getFieldDecorator={getFieldDecorator}
                        setFieldsValue={setFieldsValue}
                        value={values?.[field.name]}
                      />
                    </Col>
                  ))
                }
                {
                  fields.length === 1 && (
                    <Col span={12}>
                      <Row gutter={32} type='flex'>
                        <Col>
                          <Form.Item>
                            <Button
                              htmlType='submit'
                              type='primary'
                            >
                              Apply Filters <Icon type='filter' />
                            </Button>
                          </Form.Item>
                        </Col>
                        <Col>
                          <Form.Item>
                            <Button
                              type='danger'
                              htmlType='reset'
                              onClick={handleReset}
                            >
                              Clear Filters <Icon type='delete' />
                            </Button>
                          </Form.Item>
                        </Col>
                      </Row>
                    </Col>
                  )
                }
              </Row>
            </Col>
          </Row>
          {
            fields.length > 1 && (
              <Row gutter={32} type='flex' justify='end'>
                <Col>
                  <Form.Item>
                    <Button
                      htmlType='submit'
                      type='primary'
                    >
                      Apply Filters <Icon type='filter' />
                    </Button>
                  </Form.Item>
                </Col>
                <Col>
                  <Form.Item>
                    <Button
                      type='danger'
                      htmlType='reset'
                      onClick={handleReset}
                    >
                      Clear Filters <Icon type='delete' />
                    </Button>
                  </Form.Item>
                </Col>
              </Row>
            )
          }
        </fieldset>
      </Form>
    </div>
  )
}
export default Form.create({ name: 'filters' })(Filters)
